SourceCode.Declaration:
/// <summary>
/// Misc. event handlers related to sales order form
/// </summary>
class METSalesTableFormEventHandler
{
}

Method.Source:
    /// <summary>
    /// SalesTable_OnWritten
    /// </summary>
    /// <param name="sender">sender</param>
    /// <param name="e">e</param>
    [FormDataSourceEventHandler(formDataSourceStr(SalesTable, METSalesTable), FormDataSourceEventType::ValidatingWrite),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void SalesTable_ValidatingWrite(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun             fr              = sender.formRun();
        MetSalesTable       metSalesTable   = sender.cursor();
        SalesTable          SalesTable      = fr.dataHelper().FindDataSource(formDataSourceStr(SalesTable, SalesTable)).cursor();

        if(!metSalesTable.SalesTable && SalesTable.RecId)
        {
            metSalesTable.SalesTable = SalesTable.RecId;
        }
    }

					
    /// <summary>
	/// CB175 SalesConfirmation
    /// Perform lookup on reason code with customer as yes
    /// </summary>
    /// <param name="sender">Form Control</param>
    /// <param name="e">form control eveng args</param>
    [FormControlEventHandler(formControlStr(SalesTable, METSalesLine_ReasonId), FormControlEventType::Lookup),
     SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void METSalesLine_ReasonId_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        Query query = new Query();

        SysTableLookup      sysTableLookup  = SysTableLookup::newParameters(tableNum(ReasonTable), sender);
        QueryBuildDataSource queryBuildInventLocationDS = query.addDataSource(tableNum(ReasonTable));
        queryBuildInventLocationDS.addRange(fieldNum(ReasonTable, Cust)).value(queryValue(NoYes::Yes));
        sysTableLookup.addLookupfield(fieldNum(ReasonTable, Reason));
        sysTableLookup.addLookupfield(fieldNum(ReasonTable, Description));

        sysTableLookup.parmQuery(query);

        // Execute lookup
        sysTableLookup.performFormLookup();

        // Use FormControlCancelableSuperEventArgs to cancel call to super()
        // Prevents the system from attempting to show the lookup form twice, causing error.
        FormControlCancelableSuperEventArgs cancelableSuperEventArgs = e as FormControlCancelableSuperEventArgs;
        cancelableSuperEventArgs.CancelSuperCall();

    }
